require_once __DIR__.'/config.php';require_login();$total=(int)$db->query('SELECT COUNT(*) n FROM employees')->fetch_assoc()['n'];$active=(int)$db->query("SELECT COUNT(*) n FROM employees WHERE employment_status NOT IN ('Resigned','Retired','Separated')")->fetch_assoc()['n'];$deps=(int)$db->query("SELECT COUNT(DISTINCT department) n FROM employees WHERE department IS NOT NULL AND department<>''")->fetch_assoc()['n'];$rows=$db->query('SELECT employee_no,first_name,last_name,department,position_title,employment_status FROM employees ORDER BY created_at DESC LIMIT 8');
page_header('Dashboard');show_flash();echo '<h1>Dashboard</h1><div class="grid"><div class="card">Total employees<div class="stat">'.$total.'</div></div><div class="card">Active employees<div class="stat">'.$active.'</div></div><div class="card">Departments<div class="stat">'.$deps.'</div></div><div class="card">Your role<div class="stat">'.h(ucfirst($_SESSION['role'])).'</div></div></div><div class="card"><div class="actions"><a class="btn" href="employees.php">Manage employees</a><a class="btn muted-btn" href="reports.php">Reports</a></div><h2>Recently added employees</h2><div class="table-wrap"><table><tr><th>Employee No.</th><th>Name</th><th>Department</th><th>Position</th><th>Status</th></tr>';
while($e=$rows->fetch_assoc())echo '<tr><td>'.h($e['employee_no']).'</td><td>'.h($e['last_name'].', '.$e['first_name']).'</td><td>'.h($e['department']).'</td><td>'.h($e['position_title']).'</td><td>'.h($e['employment_status']).'</td></tr>';echo '</table></div></div>';page_footer();